        svartha: 'ආසවා ච ධම්මා ආසවසම්පයුත්තා ච - ආසව ද වන්නා වූ ද ආසව සම්ප්‍රයුක්ත ද වන්නා වූ ද නිස්සත්ව නිජ්ජීව පරමාර්ථ ස්වභාව ධර්මයෝ ඇත්තාහ.\n\nස්කන්ධ වශයෙන්: සතරකි.\nආයතන වශයෙන්: දෙකකි.\nධාතු වශයෙන්: දෙකකි.\nආර්ය සතය වශයෙන්: දෙකකි.',
