        desc: 'ලෝකික කුසල් සිත් 17, ලෝකික විපාක සිත් 32, ක්‍රියා සිත් 20, රූප 28.',
        svartha: 'අසංකිලිට්ඨසංකිලේසිකා ධම්මා - අසංකිලිට්ඨ - ක්ලේශාදී කෙලෙසුන් විසින් නොකෙලෙසන ලද්දා වූ, සංකිලේසිකා ධම්මා - ක්ලේශාදී කෙලෙසුන්ට හිත වූ නිස්සත්ව නිජ්ජීව පරමාර්ථ ස්වභාව ධර්මයෝ ඇත්තාහ.\n\nස්කන්ධ වශයෙන්: පහකි.\nආයතන වශයෙන්: දෙකකි.\nධාතු වශයෙන්: දෙකකි.\nආර්ය සතය වශයෙන්: එකකි.',
