        svartha: 'දස්සනේන පහාතබ්බා ධම්මා - සෝවාන් මාර්ගයෙන් සමුච්ඡේද වශයෙන් ප්‍රහාණය වන්නා වූ දිට්ඨිගත සම්ප්‍රයුක්ත සිත් සතර ද, විචිකිච්ඡා සහගත විත්තය ද, තත් සම්ප්‍රයුක්ත වූ මාන දෝස ඉස්සා මච්ඡරිය කුක්කුච්ච වර්ජිත චෛතසික දෙවිස්ස ද, සෝවාන් මාර්ගයෙන් තුනී කිරීම් වශයෙන් ප්‍රහාණය කටයුතු වූ අපාය ගාමිනී ශක්තිය ඇත්තා වූ දිට්ඨිගත විප්‍රයුක්ත සිත් සතර ද, දෝස මූල දෙක ද, තත් සම්ප්‍රයුක්ත වන දිට්ඨි විචිකිච්ඡා වර්ජිත පස්විසි චෛතසික ද ලැබෙන්නාහ.\n\nස්කන්ධ වශයෙන්: සතරකි.\nආයතන වශයෙන්: දෙකකි.\nධාතු වශයෙන්: දෙකකි.\nආර්ය සතය වශයෙන්: දෙකකි.',
