        svartha: 'න දස්සනේන පහාතබ්බා ධම්මා - සෝවාන් මාර්ගයෙන් ප්‍රහාණය නොවන්නා වූ අපායගාමී ශක්තියෙන් තොර වූ දිට්ඨිගත විප්පයුත්ත සිත් සතර ද දෝස මූල දෙසිත ද, සෝවාන් මාර්ගයෙන් ඒකාන්තයෙන් ප්‍රහාණය නොවන්නා වූ උද්ධච්ච සහගත සිත ද, දොළොස් අකුශල් වර්ජිත සත් සැත්තෑ විත්තය ද, දිට්ඨි විචිකිච්ඡා වර්ජිත චෛතසික සමපණස ද, අටවිසි රූපය ද නිර්වාණ ධාතුව ද ලැබෙන්නාහ.\n\nස්කන්ධ වශයෙන්: පසකි.\nආයතන වශයෙන්: දොළොසකි.\nධාතු වශයෙන්: අටළොසකි.\nආර්ය සතය වශයෙන්: සතරකි.',
